{
  "project_id": "610f82ef25fa49c39653",
  "name": "fix_notes_rls_user_isolation",
  "query": "drop policy if exists "read notes" on public.notes;
drop policy if exists "update own notes" on public.notes;

create policy "read notes"
on public.notes
for select
to authenticated
using ((select auth.uid()) is not null and (select auth.uid()) = user_id);

create policy "update own notes"
on public.notes
for update
to authenticated
using ((select auth.uid()) is not null and (select auth.uid()) = user_id)
with check ((select auth.uid()) is not null and (select auth.uid()) = user_id);"
}

